import { PickD3Scale } from '@visx/scale';
import clsx from 'clsx';
import React, { useEffect, useRef } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { svgPlotLayout } from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { VerticalCrosshair } from '../../../../core/components/crosshair/VerticalCrosshair.js';
import {
  BRUSH_HOVER_FILL,
  BRUSH_STYLES,
} from '../../../../core/components/overlays/constants.js';
import { useExploreKeyboardMovementHandlers } from '../../../../core/components/overlays/hooks/useExploreKeyboardMovementHandlers.js';
import { useKeyboardControls } from '../../../../core/components/overlays/hooks/useKeyboardControls.js';
import { isZoomBoundaries } from '../../../../core/functions/zoom.js';
import { useSetState, useZoomState } from '../../../hooks/store/selectors.js';
import { useChartInteractions } from '../../../hooks/useChartInteractions.js';
import { useTimeseriesXFormatter } from '../../../hooks/useTimeseriesXFormatter.js';
import { useXScales } from '../../../hooks/useXScale.js';
import { brushOverlay } from '../TimeseriesOverlays.sty.js';

export const TimeseriesExploreKeyboardOverlay = () => {
  const { width, height } = useGridPlotSize();

  const { currentScale: xScale, initialScale } = useXScales();
  const { onZoomChange } = useChartInteractions();
  const { zoomInEnabled } = useZoomState();
  const zoomInDisabled = !zoomInEnabled;
  const setState = useSetState();
  const xFormatter = useTimeseriesXFormatter();

  const groupRef = useRef<SVGSVGElement>(null);
  const rectRef = useRef<SVGRectElement>(null);
  const leftLineRef = useRef<SVGLineElement>(null);
  const rightLineRef = useRef<SVGLineElement>(null);

  const {
    positionX,
    selectionAreaWidth,
    windowMovement,
    leftLineMovement,
    rightLineMovement,
  } = useExploreKeyboardMovementHandlers({
    width,
    leftLineRef,
    rightLineRef,
  });

  const handleZoomModeCancel = () => {
    setState((prev) => ({
      ...prev,
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: prev.zoom.activeKeyboardMode,
        activeKeyboardMode: undefined,
      },
    }));
  };

  const handleApplyZoom = () => {
    if (zoomInDisabled) {
      return;
    }

    const newDomainStart = (xScale as PickD3Scale<'time'>).invert(positionX);
    const newDomainEnd = (xScale as PickD3Scale<'time'>).invert(
      selectionAreaWidth + positionX,
    );
    const newDomain = [newDomainStart, newDomainEnd];

    const { isMaxZoom, isMinZoom } = isZoomBoundaries(
      initialScale.domain() as Date[],
      xScale.domain(),
      newDomain,
    );

    onZoomChange && onZoomChange(newDomainStart, newDomainEnd, 'zoom-x');

    setState((prev) => ({
      ...prev,
      currentDomain: newDomain,
      zoom: {
        ...prev.zoom,
        zoomInEnabled: !isMaxZoom,
        zoomOutEnabled: !isMinZoom,
        keyboardFocusMode: prev.zoom.activeKeyboardMode,
        activeKeyboardMode: undefined,
      },
    }));
  };

  useKeyboardControls({
    ref: rectRef,
    onLeft: windowMovement('left'),
    onRight: windowMovement('right'),
  });

  useKeyboardControls({
    ref: leftLineRef,
    onLeft: leftLineMovement('left'),
    onRight: leftLineMovement('right'),
  });

  useKeyboardControls({
    ref: rightLineRef,
    onLeft: rightLineMovement('left'),
    onRight: rightLineMovement('right'),
  });

  useKeyboardControls({
    ref: groupRef,
    onAccept: handleApplyZoom,
    onCancel: handleZoomModeCancel,
  });

  useEffect(() => rectRef.current?.focus(), []);

  const getBrushLabelFromPoint = (x: number): string => {
    const xTime = (xScale as PickD3Scale<'time'>).invert(x);

    return xFormatter(xTime);
  };

  return (
    <svg ref={groupRef} className={clsx(svgPlotLayout, brushOverlay)}>
      <rect
        ref={rectRef}
        x={positionX}
        y={0}
        width={selectionAreaWidth}
        height={height}
        fill={BRUSH_HOVER_FILL}
        stroke={BRUSH_STYLES.stroke}
        opacity={BRUSH_STYLES.opacity}
        tabIndex={0}
        data-testid="zoom-x-window"
      />
      <VerticalCrosshair
        ref={leftLineRef}
        data-testid="a11y-vertical-crosshair-brush-start"
        x={positionX}
        label={getBrushLabelFromPoint(positionX)}
        height={height}
        dashed={false}
        color={Colors.Background.Field.Primary.Accent}
        focusable
      />
      <VerticalCrosshair
        ref={rightLineRef}
        data-testid="a11y-vertical-crosshair-brush-end"
        x={positionX + selectionAreaWidth}
        label={getBrushLabelFromPoint(positionX + selectionAreaWidth)}
        height={height}
        dashed={false}
        color={Colors.Background.Field.Primary.Accent}
        focusable
      />
    </svg>
  );
};

TimeseriesExploreKeyboardOverlay['displayName'] =
  'TimeseriesExploreKeyboardOverlay';
